    m.append(S('s-mem', '🧠', '速记：雅歌一页通',
        C('mem', '口诀「一歌三惊，五一园门；四七无瑕，七十恋慕；八六印记，众水难灭」', '<b>一歌</b>：1:1 歌中的雅歌；<b>三惊</b>：2:7；3:5；8:4 不要惊动；<b>五一园门</b>：5:1 中心；<b>四七无瑕</b>：4:7；<b>七十恋慕</b>：7:10 翻转创3:16；<b>八六印记</b>：8:6；<b>众水难灭</b>：8:7。') +
        cards_flip([('歌2:16', '良人属我，我也属他；他在百合花中牧放群羊。'), ('歌4:7', '我的佳偶，你全然美丽，毫无瑕疵！'), ('歌7:10', '我属我的良人，他也恋慕我。（翻转创3:16）'),
                    ('歌8:6', '求你将我放在你心上如印记，带在你臂上如戳记。'), ('歌8:7', '爱情，众水不能息灭，大水也不能淹没。'), ('弗5:32', '这是极大的奥秘，但我是指着基督和教会说的。')]) +
        quiz('so', [('雅歌的副歌“不要惊动”出现几次？', ['1', '2', '3', '7'], 2, '2:7；3:5；8:4。'), ('三项联合信条的 CCI 脚注引用雅歌几次？', ['0', '3', '7', '12'], 0, '一次也没有。'),
                    ('7:10“恋慕”一词还出现在？', ['创1:28', '创3:16；4:7', '出20:14', '诗45'], 1, 'teshuqah 只出现三次。'), ('1544 年在日内瓦为雅歌正典地位辩护的是？', ['路德', '加尔文', '慈运理', '伯撒'], 1, '加尔文与卡斯特利奥之争。')])))
    return hr, ''.join(m)
